<template><div class="state" :aria-live="state==='loading'?'polite':'assertive'"><span v-if="state==='loading'" class="spinner"/><svg v-else viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="12" cy="12" r="9"/><path v-if="state==='error'" d="M12 7v6m0 4h.01"/><path v-else d="m8 12 2.5 2.5L16 9"/></svg><strong>{{title||defaults[state]}}</strong><p v-if="description">{{description}}</p><slot name="action"/></div></template>
<script setup>defineProps({state:{type:String,default:"empty"},title:String,description:String});const defaults={loading:"正在加载",empty:"暂无内容",error:"加载失败",success:"操作成功"};</script>
<style scoped>.state{display:flex;flex-direction:column;align-items:center;gap:8px;padding:48px 24px;color:var(--fm-ink-muted);text-align:center}.state svg{width:42px;height:42px;opacity:.45}.state strong{color:var(--fm-ink-soft);font-size:15px}.state p{max-width:430px;margin:0;font-size:13px}.spinner{width:28px;height:28px;border:2px solid var(--fm-line);border-right-color:var(--fm-accent);border-radius:50%;animation:spin .75s linear infinite}</style>
